69	    pub fn open(db_path: &std::path::Path) -> Result<Self> {
70	        if let Some(parent) = db_path.parent() {
71	            std::fs::create_dir_all(parent)?;
72	        }
73	
74	        let conn = Connection::open(db_path)?;
75	        let _ = conn.execute_batch(
76	            "PRAGMA journal_mode=WAL;
77	             PRAGMA busy_timeout=5000;",
78	        );
79	
80	        conn.execute(
81	            "CREATE TABLE IF NOT EXISTS provenance_records (
82	                id INTEGER PRIMARY KEY,
83	                model_id TEXT NOT NULL DEFAULT 'unknown',
84	                model_version TEXT NOT NULL DEFAULT '',
85	                prompt_hash TEXT NOT NULL DEFAULT '',
86	                code_hash TEXT NOT NULL,
87	                file_path TEXT NOT NULL,
88	                start_line INTEGER NOT NULL DEFAULT 0,
89	                end_line INTEGER NOT NULL DEFAULT 0,
90	                contributor_type TEXT NOT NULL DEFAULT 'unknown',
91	                attestation_sig TEXT NOT NULL,
92	                timestamp TEXT NOT NULL,
93	                developer_id TEXT NOT NULL DEFAULT '',
94	                session_id TEXT NOT NULL DEFAULT ''
95	            )",
96	            [],
97	        )?;
98	
99	        conn.execute(
100	            "CREATE INDEX IF NOT EXISTS idx_prov_file ON provenance_records(file_path)",
101	            [],
102	        )?;
103	        conn.execute(
104	            "CREATE INDEX IF NOT EXISTS idx_prov_session ON provenance_records(session_id)",
105	            [],
106	        )?;
107	        conn.execute(
108	            "CREATE INDEX IF NOT EXISTS idx_prov_timestamp ON provenance_records(timestamp)",
109	            [],
110	        )?;
111	
112	        conn.execute(
113	            "CREATE TABLE IF NOT EXISTS provenance_snapshots (
114	                id INTEGER PRIMARY KEY,
115	                file_path TEXT NOT NULL UNIQUE,
116	                content_hash TEXT NOT NULL,
117	                timestamp TEXT NOT NULL
118	            )",
119	            [],
120	        )?;
121	        conn.execute(
122	            "CREATE INDEX IF NOT EXISTS idx_snap_file ON provenance_snapshots(file_path)",
123	            [],
124	        )?;
125	
126	        Ok(Self { conn })
127	    }
