233	    pub fn save_snapshot(&self, file_path: &str, content_hash: &str) -> Result<()> {
234	        let timestamp = chrono::Utc::now().to_rfc3339();
235	        self.conn.execute(
236	            "INSERT OR REPLACE INTO provenance_snapshots (file_path, content_hash, timestamp)
237	             VALUES (?1, ?2, ?3)",
238	            params![file_path, content_hash, timestamp],
239	        )?;
240	        Ok(())
241	    }
242	
243	    pub fn get_snapshot(&self, file_path: &str) -> Result<Option<String>> {
244	        let result = self.conn.query_row(
245	            "SELECT content_hash FROM provenance_snapshots WHERE file_path = ?1",
246	            params![file_path],
247	            |row| row.get(0),
248	        );
249	        match result {
250	            Ok(hash) => Ok(Some(hash)),
251	            Err(rusqlite::Error::QueryReturnedNoRows) => Ok(None),
252	            Err(e) => Err(e.into()),
253	        }
254	    }
255	
256	    pub fn cleanup_old_records(&self) -> Result<usize> {
257	        let cutoff = chrono::Utc::now() - chrono::Duration::days(RETENTION_DAYS);
258	        let deleted = self.conn.execute(
259	            "DELETE FROM provenance_records WHERE timestamp < ?1",
260	            params![cutoff.to_rfc3339()],
261	        )?;
262	        Ok(deleted)
263	    }
264	}
