266	pub fn create_signed_record(
267	    file_path: &str,
268	    code_content: &[u8],
269	    start_line: u32,
270	    end_line: u32,
271	    session_id: &str,
272	) -> Result<ProvenanceRecord> {
273	    let keypair = attestation::load_or_generate()
274	        .context("failed to load attestation keypair")?;
275	
276	    let code_hash = content_hash::hash_content(code_content);
277	    let timestamp = chrono::Utc::now().to_rfc3339();
278	
279	    let sign_payload = format!("{}:{}:{}", file_path, code_hash, timestamp);
280	    let sig = keypair.sign(sign_payload.as_bytes());
281	
282	    Ok(ProvenanceRecord {
283	        id: None,
284	        model_id: "unknown".to_string(),
285	        model_version: String::new(),
286	        prompt_hash: String::new(),
287	        code_hash,
288	        file_path: file_path.to_string(),
289	        start_line,
290	        end_line,
291	        contributor_type: ContributorType::Ai,
292	        attestation_sig: sig,
293	        timestamp,
294	        developer_id: whoami(),
295	        session_id: session_id.to_string(),
296	    })
297	}
