100	pub fn run_enrich(session_id: &str, model_id: &str) -> Result<()> {
101	    let store = ProvenanceStore::new()?;
102	    let updated = store.enrich_model_id(session_id, model_id)?;
103	    println!("Enriched {} record(s) in session {}", updated, session_id);
104	    Ok(())
105	}
