use anyhow::{Context, Result};
use colored::Colorize;
use std::path::PathBuf;

use crate::core::dep_validator::Severity;
use crate::core::hallucination_detector::{CheckType, Finding};
use crate::core::quality_gate::{self, GateResult, QualityConfig};

/// Run the quality gate over staged or all project files.
pub fn run_gate(all: bool, json: bool) -> Result<()> {
    let config = QualityConfig::load();
    let files = collect_files(all)?;

    if files.is_empty() {
        println!("{}", "GATE PASSED: no files to scan".green().bold());
        return Ok(());
    }

    let result = quality_gate::run_gate(&files, &config)
        .context("quality gate execution failed")?;

    if json {
        print_json(&result);
    } else {
        print_human(&result, &config);
    }

    if !result.passed {
        std::process::exit(1);
    }

    Ok(())
}

/// Run the gate and return the exit code (for main.rs dispatch).
pub fn run_gate_with_exit(all: bool, json: bool) -> Result<i32> {
    let config = QualityConfig::load();
    let files = collect_files(all)?;

    if files.is_empty() {
        println!("{}", "GATE PASSED: no files to scan".green().bold());
        return Ok(0);
    }

    let result = quality_gate::run_gate(&files, &config)
        .context("quality gate execution failed")?;

    if json {
        print_json(&result);
    } else {
        print_human(&result, &config);
    }

    if result.passed {
        Ok(0)
    } else {
        Ok(1)
    }
}

fn collect_files(all: bool) -> Result<Vec<PathBuf>> {
    if all {
        collect_all_project_files()
    } else {
        collect_staged_files()
    }
}

/// Get git-staged files via `git diff --staged --name-only`.
fn collect_staged_files() -> Result<Vec<PathBuf>> {
    let output = std::process::Command::new("git")
        .args(["diff", "--staged", "--name-only"])
        .output();

    match output {
        Ok(out) if out.status.success() => {
            let files: Vec<PathBuf> = String::from_utf8_lossy(&out.stdout)
                .lines()
                .filter(|l| !l.is_empty())
                .map(PathBuf::from)
                .filter(|p| p.exists())
                .collect();
            Ok(files)
        }
        Ok(_) => {
            // git ran but returned non-zero (e.g., not a git repo) — scan nothing
            eprintln!("[rtk quality] warning: not in a git repo, use --all to scan all files");
            Ok(vec![])
        }
        Err(e) => {
            eprintln!("[rtk quality] warning: git not available: {}", e);
            Ok(vec![])
        }
    }
}

/// Walk the project directory and collect all scannable files.
fn collect_all_project_files() -> Result<Vec<PathBuf>> {
    let ignore_dirs = ["node_modules", "vendor", ".git", "target", "dist", "build"];
    let scan_exts = ["js", "ts", "jsx", "tsx", "mjs", "cjs", "py", "toml", "rs"];

    let mut files = Vec::new();
    for entry in walkdir::WalkDir::new(".")
        .follow_links(false)
        .into_iter()
        .filter_entry(|e| {
            let name = e.file_name().to_string_lossy();
            !ignore_dirs.iter().any(|d| name == *d)
        })
        .filter_map(|e| e.ok())
    {
        if !entry.file_type().is_file() {
            continue;
        }
        let ext = entry
            .path()
            .extension()
            .and_then(|e| e.to_str())
            .unwrap_or("");
        if scan_exts.contains(&ext) {
            files.push(entry.path().to_path_buf());
        }
    }
    Ok(files)
}

fn print_human(result: &GateResult, config: &QualityConfig) {
    if result.findings.is_empty() {
        println!(
            "{}",
            format!(
                "GATE PASSED: {} file(s) scanned, 0 findings",
                result.stats.files_scanned
            )
            .green()
            .bold()
        );
        return;
    }

    // Print findings grouped by severity
    println!();
    for finding in &result.findings {
        print_finding(finding);
    }
    println!();

    // Summary line
    let critical = result.stats.findings_by_severity.get("critical").copied().unwrap_or(0);
    let high = result.stats.findings_by_severity.get("high").copied().unwrap_or(0);
    let medium = result.stats.findings_by_severity.get("medium").copied().unwrap_or(0);
    let low = result.stats.findings_by_severity.get("low").copied().unwrap_or(0);

    if result.passed {
        println!(
            "{}",
            format!(
                "GATE PASSED: {} file(s) scanned, {} finding(s) [{}c {}h {}m {}l] — none block",
                result.stats.files_scanned, result.findings.len(), critical, high, medium, low
            )
            .green()
            .bold()
        );
    } else {
        let blocking: usize = result
            .findings
            .iter()
            .filter(|f| config.is_blocking(f.severity))
            .count();
        println!(
            "{}",
            format!(
                "GATE FAILED: {} critical, {} high — {} blocking finding(s) in {} file(s)",
                critical, high, blocking, result.stats.files_scanned
            )
            .red()
            .bold()
        );
    }
}

fn print_finding(f: &Finding) {
    let severity_label = match f.severity {
        Severity::Critical => format!("[CRITICAL]").red().bold().to_string(),
        Severity::High => format!("[HIGH]").yellow().bold().to_string(),
        Severity::Medium => format!("[MEDIUM]").cyan().to_string(),
        Severity::Low => format!("[LOW]").white().dimmed().to_string(),
    };

    let check_label = format!("[{}]", f.check_type.as_str()).dimmed();

    let location = if f.line > 0 {
        format!("{}:{}", f.file_path, f.line)
    } else {
        f.file_path.clone()
    };

    println!("{} {} {}", severity_label, check_label, location.bold());
    println!("  {}", f.message);
    if let Some(ref sug) = f.suggestion {
        println!("  {} {}", "hint:".dimmed(), sug.dimmed());
    }
}

fn print_json(result: &GateResult) {
    match serde_json::to_string_pretty(result) {
        Ok(s) => println!("{}", s),
        Err(e) => eprintln!("[rtk quality] JSON serialization error: {}", e),
    }
}

