    use crate::core::hallucination_detector::{CheckType, Finding};
    use crate::core::quality_gate::{GateResult, GateStats};
    use std::collections::HashMap;

    fn make_result(findings: Vec<Finding>, passed: bool) -> GateResult {
        let mut by_sev = HashMap::new();
        for f in &findings {
            *by_sev.entry(f.severity.as_str().to_string()).or_insert(0usize) += 1;
        }
        GateResult {
            findings,
            passed,
            stats: GateStats {
                files_scanned: 1,
                deps_checked: 0,
                findings_by_severity: by_sev,
            },
        }
    }

    #[test]
    fn print_human_no_findings() {
        // Just verifies it doesn't panic
        let cfg = QualityConfig::default();
        let result = make_result(vec![], true);
        print_human(&result, &cfg);
    }

    #[test]
    fn print_human_with_critical() {
        let cfg = QualityConfig::default();
        let finding = Finding {
            check_type: CheckType::HardcodedSecret,
