/// Run the quality gate over staged or all project files.
pub fn run_gate(all: bool, json: bool) -> Result<()> {
    let config = QualityConfig::load();
    let files = collect_files(all)?;

    if files.is_empty() {
        println!("{}", "GATE PASSED: no files to scan".green().bold());
        return Ok(());
