    let result = quality_gate::run_gate(&files, &config)
        .context("quality gate execution failed")?;

    if json {
        print_json(&result);
    } else {
        print_human(&result, &config);
    }

    if !result.passed {
        std::process::exit(1);
    }

    Ok(())
}

